import java.util.Scanner;

public class Main {
    public static int countDigitsInNumber(long n) {
        int count = 0;
        while (n != 0) {
            n /= 10;
            count++;
        }
        return count;
    }

    public static long getMaxRepeatingOneNumber(long n) {
        int length = countDigitsInNumber(n);
        long sum = 0, power = 1;
        for (int i = 0; i < length; i++) {
            sum += power;
            power *= 10;
        }
        if (sum <= n) return sum;
        return (sum - 1) / 10;
    }

    public static long computeResult(long n) {
        if (n <= 6) return n;
        if (n <= 11) return 13 - n;
        long base = getMaxRepeatingOneNumber(n);
        long nextNum = base * 10 + 1;
        if (n % base == 0) {
            if (n <= (nextNum / 2 + base))
                return countDigitsInNumber(base) * n / base;
            return countDigitsInNumber(nextNum) + computeResult(nextNum - n);
        } else {
            long m = (n / base) * base;
            long res = computeResult(m) + computeResult(n - m);
            if (n > nextNum / 2)
                res = Math.min(computeResult(m) + computeResult(n - m),
                               countDigitsInNumber(nextNum) + computeResult(nextNum - n));
            return res;
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        System.out.println(computeResult(n));
        scanner.close();
    }
}
